/// <summary>
/// T047: the OpenAPI document that the HttpApi module produces when it is hosted. The document is generated by the
/// sample host (ABP + Swashbuckle) and checked here as a contract: valid OpenAPI, the exact set of operations,
/// how each operation takes its input, and what the schemas promise.
/// </summary>
[Collection(HostCollection.Name)]
